def profiles(apps, schema_editor):
    """Give the people who signed in before their profile with the GitHub name."""
    Profile = apps.get_model("pycal_dashboard", "Profile")
    SocialAccount = apps.get_model("socialaccount", "SocialAccount")
    for account in SocialAccount.objects.filter(provider="github"):
        login = str((account.extra_data or {}).get("login") or "")
        Profile.objects.update_or_create(
            user_id=account.user_id, defaults={"github_name": login, "github_id": account.uid}
        )


